/**
 * MapML's tiled coordinate reference systems: OSMTILE, WGS84, CBMTILE and
 * APSTILE, ported from MapML.js `src/mapml/GlobalM.js` (`M.OSMTILE`,
 * `M.WGS84`, `M.CBMTILE`, `M.APSTILE`) together with the parts of
 * Proj4Leaflet's `Proj.CRS` and Leaflet's `CRS.EPSG3857` that MapML.js
 * reaches through them (`project`, `unproject`, `transformation`,
 * `scale`, `zoom`).
 *
 * Each CRS keeps MapML.js's shape: `origin`, `bounds` (PCRS),
 * `resolutions`, and a `crs` object describing the six MapML coordinate
 * systems' axes (`tcrs`, `pcrs`, `gcrs`, `map`, `tile`, `tilematrix`),
 * so code ported from MapML.js that reads `M[projection].options.crs…`
 * reads the same values here.
 *
 * Renderer concerns (how MapLibre draws a CRS) live elsewhere; this
 * module is pure MapML coordinate math.
 */
import proj4 from 'proj4';

/** The CRS names MapML defines. `GLOBE` is a deprecated alias of OSMTILE. */
export const MAPML_CRS_NAMES = ['OSMTILE', 'WGS84', 'CBMTILE', 'APSTILE'] as const;

export type MapmlCrsName = (typeof MAPML_CRS_NAMES)[number];

/** A PCRS bounding box, `{ min: [x, y], max: [x, y] }`. */
export interface Bounds {
  min: [number, number];
  max: [number, number];
}

interface Axis<T> {
  readonly name: string;
  readonly min: number;
  readonly max: T;
}

interface AxisPairDef<T> {
  readonly horizontal: Axis<T>;
  readonly vertical: Axis<T>;
}

/** MapML.js's `M[projection].options.crs`: the axes of each coordinate system. */
export interface CrsAxes {
  /** Tiled CRS pixels at a zoom: `x`, `y`; maxima depend on the zoom. */
  readonly tcrs: AxisPairDef<(zoom: number) => number> & { bounds(zoom: number): Bounds };
  /** Projected CRS: `easting`, `northing` (WGS84: `longitude`, `latitude`). */
  readonly pcrs: AxisPairDef<number> & { readonly bounds: Bounds };
  /** Geographic CRS: `longitude`, `latitude`. */
  readonly gcrs: AxisPairDef<number> & { readonly bounds: Bounds };
  /** Map viewport pixels: `i`, `j`; maxima are the map's size. */
  readonly map: AxisPairDef<(size: [number, number]) => number>;
  /** Pixels within a tile: `i`, `j`. */
  readonly tile: AxisPairDef<number> & { readonly bounds: Bounds };
  /** Tile column / row at a zoom; maxima depend on the zoom. */
  readonly tilematrix: AxisPairDef<(zoom: number) => number> & {
    bounds(zoom: number): Bounds;
  };
}

/**
 * A MapML tiled CRS: the `Proj.CRS` / `CRS.EPSG3857` instance MapML.js
 * keeps as `M[projection]`, with its `options` flattened onto it.
 */
export interface TiledCrs {
  /** MapML name, e.g. `CBMTILE`. */
  readonly name: string;
  /** EPSG code (or, for a custom projection, its name). */
  readonly code: string;
  /** proj4 definition string. */
  readonly proj4: string;
  /** PCRS of TCRS pixel (0, 0): the top-left corner of the tile matrix. */
  readonly origin: readonly [number, number];
  /** The PCRS extent of the tile matrix. */
  readonly bounds: Bounds;
  /** PCRS units per pixel, one per zoom level. */
  readonly resolutions: readonly number[];
  readonly tileSize: number;
  readonly crs: CrsAxes;
  /** `[lon, lat]` → PCRS `[x, y]`. */
  project(lon: number, lat: number): [number, number];
  /** PCRS `[x, y]` → `[lon, lat]`; positions without one come back as 0. */
  unproject(x: number, y: number): [number, number];
  /** Pixels per PCRS unit at a (possibly fractional) zoom. */
  scale(zoom: number): number;
  /** The (possibly fractional) zoom of a scale; ±Infinity outside the table. */
  zoom(scale: number): number;
  /** PCRS → TCRS pixels at `scale`. */
  transform(x: number, y: number, scale: number): [number, number];
  /** TCRS pixels at `scale` → PCRS. */
  untransform(x: number, y: number, scale: number): [number, number];
}

/** M.TILE_SIZE */
export const TILE_SIZE = 256;

const sizeOf = (b: Bounds): [number, number] => [b.max[0] - b.min[0], b.max[1] - b.min[1]];

/**
 * The `crs` axes object MapML.js writes out per projection (and builds
 * from a template in `defineCustomProjection`). `gcrsRange` is the EPSG
 * area of use MapML.js hard-codes for its built-in CRSs; without it the
 * range is the corners of `gcrsFrom()` unprojected: the PCRS bounds by
 * default, as MapML.js does for OSMTILE, and for custom projections
 * OSMTILE's bounds, as MapML.js's `defineCustomProjection` does.
 */
function crsAxes(
  self: () => TiledCrs,
  pcrsNames: [string, string],
  gcrsRange?: { lon: [number, number]; lat: [number, number] },
  gcrsFrom?: () => Bounds
): CrsAxes {
  const gcrsCorner = (corner: 'min' | 'max') => {
    const c = (gcrsFrom ? gcrsFrom() : self().bounds)[corner];
    return self().unproject(c[0], c[1]);
  };
  const crs: CrsAxes = {
    tcrs: {
      horizontal: {
        name: 'x',
        min: 0,
        max: (zoom) => Math.round(sizeOf(self().bounds)[0] / self().resolutions[zoom]!)
      },
      vertical: {
        name: 'y',
        min: 0,
        max: (zoom) => Math.round(sizeOf(self().bounds)[1] / self().resolutions[zoom]!)
      },
      bounds: (zoom) => ({
        min: [crs.tcrs.horizontal.min, crs.tcrs.vertical.min],
        max: [crs.tcrs.horizontal.max(zoom), crs.tcrs.vertical.max(zoom)]
      })
    },
    pcrs: {
      horizontal: {
        name: pcrsNames[0],
        get min() {
          return self().bounds.min[0];
        },
        get max() {
          return self().bounds.max[0];
        }
      },
      vertical: {
        name: pcrsNames[1],
        get min() {
          return self().bounds.min[1];
        },
        get max() {
          return self().bounds.max[1];
        }
      },
      get bounds() {
        return self().bounds;
      }
    },
    gcrs: {
      horizontal: {
        name: 'longitude',
        get min() {
          return gcrsRange ? gcrsRange.lon[0] : gcrsCorner('min')[0];
        },
        get max() {
          return gcrsRange ? gcrsRange.lon[1] : gcrsCorner('max')[0];
        }
      },
      vertical: {
        name: 'latitude',
        get min() {
          return gcrsRange ? gcrsRange.lat[0] : gcrsCorner('min')[1];
        },
        get max() {
          return gcrsRange ? gcrsRange.lat[1] : gcrsCorner('max')[1];
        }
      },
      get bounds(): Bounds {
        return {
          min: [crs.gcrs.horizontal.min, crs.gcrs.vertical.min],
          max: [crs.gcrs.horizontal.max, crs.gcrs.vertical.max]
        };
      }
    },
    map: {
      horizontal: { name: 'i', min: 0, max: (size) => size[0] },
      vertical: { name: 'j', min: 0, max: (size) => size[1] }
    },
    tile: {
      horizontal: { name: 'i', min: 0, max: self().tileSize },
      vertical: { name: 'j', min: 0, max: self().tileSize },
      get bounds(): Bounds {
        return {
          min: [crs.tile.horizontal.min, crs.tile.vertical.min],
          max: [crs.tile.horizontal.max, crs.tile.vertical.max]
        };
      }
    },
    tilematrix: {
      horizontal: {
        name: 'column',
        min: 0,
        max: (zoom) =>
          Math.round(crs.tcrs.horizontal.max(zoom) / sizeOf(crs.tile.bounds)[0])
      },
      vertical: {
        name: 'row',
        min: 0,
        max: (zoom) =>
          Math.round(crs.tcrs.vertical.max(zoom) / sizeOf(crs.tile.bounds)[1])
      },
      bounds: (zoom) => ({
        min: [crs.tilematrix.horizontal.min, crs.tilematrix.vertical.min],
        max: [crs.tilematrix.horizontal.max(zoom), crs.tilematrix.vertical.max(zoom)]
      })
    }
  };
  return crs;
}

/**
 * Proj4Leaflet's `scale(zoom)` / `zoom(scale)` over a table of scales:
 * linear interpolation between levels.
 */
function scaleTable(resolutions: readonly number[]) {
  const scales = resolutions.map((r) => 1 / r);
  const closestBelow = (s: number): number | undefined => {
    let low: number | undefined;
    for (let i = scales.length; i--; ) {
      if (scales[i]! <= s && (low === undefined || low < scales[i]!)) low = scales[i];
    }
    return low;
  };
  return {
    scale(zoom: number): number {
      const iZoom = Math.floor(zoom);
      if (zoom === iZoom) return scales[zoom]!;
      const base = scales[iZoom]!;
      return base + (scales[iZoom + 1]! - base) * (zoom - iZoom);
    },
    zoom(scale: number): number {
      const down = closestBelow(scale);
      if (down === undefined) return -Infinity;
      const downZoom = scales.indexOf(down);
      if (scale === down) return downZoom;
      const next = scales[downZoom + 1];
      if (next === undefined) return Infinity;
      return (scale - down) / (next - down) + downZoom;
    }
  };
}

export interface TiledCrsDefinition {
  name: string;
  code: string;
  proj4: string;
  origin: [number, number];
  bounds: Bounds;
  resolutions: readonly number[];
  tileSize?: number;
  /** PCRS axis names; `['easting', 'northing']` unless geographic. */
  pcrsAxes?: [string, string];
  /** EPSG area of use; derived from `bounds` when omitted. */
  gcrsRange?: { lon: [number, number]; lat: [number, number] };
  /** The PCRS box whose corners, unprojected, give the gcrs range; `bounds` when omitted. */
  gcrsFrom?: () => Bounds;
}

/**
 * A `Proj.CRS`: proj4 for `project` / `unproject`, and the transformation
 * `(1, -origin.x, -1, origin.y)` scaled by `1 / resolutions[zoom]`.
 */
export function createTiledCrs(def: TiledCrsDefinition): TiledCrs {
  const converter = proj4('EPSG:4326', def.proj4);
  const table = scaleTable(def.resolutions);
  const [ox, oy] = def.origin;
  const crsObj: TiledCrs = {
    name: def.name,
    code: def.code,
    proj4: def.proj4,
    origin: def.origin,
    bounds: def.bounds,
    resolutions: def.resolutions,
    tileSize: def.tileSize ?? TILE_SIZE,
    crs: undefined as unknown as CrsAxes,
    project(lon, lat) {
      const p = converter.forward([lon, lat]);
      return [p[0]!, p[1]!];
    },
    unproject(x, y) {
      const ll = converter.inverse([x, y]);
      // Proj4Leaflet: 0 rather than NaN where there is no earth location.
      return [ll[0]! || 0, ll[1]! || 0];
    },
    scale: table.scale,
    zoom: table.zoom,
    transform(x, y, scale) {
      return [scale * (x - ox), scale * (oy - y)];
    },
    untransform(x, y, scale) {
      return [x / scale + ox, oy - y / scale];
    }
  };
  (crsObj as { crs: CrsAxes }).crs = crsAxes(
    () => crsObj,
    def.pcrsAxes ?? ['easting', 'northing'],
    def.gcrsRange,
    def.gcrsFrom
  );
  return crsObj;
}

// ---- OSMTILE: Leaflet's CRS.EPSG3857 with MapML.js's options --------------

/** Web Mercator sphere radius, meters. */
const EARTH_RADIUS = 6378137;
/** Half the Web Mercator world width, meters (≈ 20037508.342789244). */
const HALF_CIRCUMFERENCE = Math.PI * EARTH_RADIUS;
/**
 * Web Mercator's valid latitude limit, degrees; beyond it the projection
 * runs to infinity, so latitudes are clamped before projecting.
 */
export const MAX_MERCATOR_LATITUDE = 85.05112878;

function createOsmtile(): TiledCrs {
  const bounds: Bounds = {
    min: [-20037508.342787, -20037508.342787],
    max: [20037508.342787, 20037508.342787]
  };
  const crsObj: TiledCrs = {
    name: 'OSMTILE',
    code: 'EPSG:3857',
    proj4:
      '+proj=merc +a=6378137 +b=6378137 +lat_ts=0 +lon_0=0 +x_0=0 +y_0=0 +k=1 +units=m +nadgrids=@null +wktext +no_defs',
    origin: [-20037508.342787, 20037508.342787],
    bounds,
    resolutions: [
      156543.0339, 78271.51695, 39135.758475, 19567.8792375, 9783.93961875,
      4891.969809375, 2445.9849046875, 1222.9924523438, 611.49622617188,
      305.74811308594, 152.87405654297, 76.437028271484, 38.218514135742,
      19.109257067871, 9.5546285339355, 4.7773142669678, 2.3886571334839,
      1.1943285667419, 0.59716428337097, 0.29858214168549, 0.14929107084274,
      0.074645535421371, 0.03732276771068573, 0.018661383855342865,
      0.009330691927671432495
    ],
    tileSize: TILE_SIZE,
    crs: undefined as unknown as CrsAxes,
    // Spherical Mercator (Leaflet SphericalMercator), latitude clamped.
    project(lon, lat) {
      const clamped = Math.max(Math.min(lat, MAX_MERCATOR_LATITUDE), -MAX_MERCATOR_LATITUDE);
      return [
        (lon * HALF_CIRCUMFERENCE) / 180,
        Math.log(Math.tan(((90 + clamped) * Math.PI) / 360)) * EARTH_RADIUS
      ];
    },
    unproject(x, y) {
      return [
        (x / HALF_CIRCUMFERENCE) * 180,
        (Math.atan(Math.exp(y / EARTH_RADIUS)) * 360) / Math.PI - 90
      ];
    },
    // Leaflet CRS.scale / zoom: 256 * 2^zoom.
    scale: (zoom) => TILE_SIZE * Math.pow(2, zoom),
    zoom: (scale) => Math.log(scale / TILE_SIZE) / Math.LN2,
    // Leaflet EPSG3857 transformation (0.5/πR, 0.5, -0.5/πR, 0.5).
    transform(x, y, scale) {
      return [
        scale * (x / (2 * HALF_CIRCUMFERENCE) + 0.5),
        scale * (-y / (2 * HALF_CIRCUMFERENCE) + 0.5)
      ];
    },
    untransform(x, y, scale) {
      return [
        2 * HALF_CIRCUMFERENCE * (x / scale - 0.5),
        2 * HALF_CIRCUMFERENCE * (0.5 - y / scale)
      ];
    }
  };
  (crsObj as { crs: CrsAxes }).crs = crsAxes(() => crsObj, ['easting', 'northing']);
  return crsObj;
}

