const OSMTILE = createOsmtile();

const registry = new Map<string, TiledCrs>([
  ['OSMTILE', OSMTILE],
  ['WGS84', WGS84],
  ['CBMTILE', CBMTILE],
  ['APSTILE', APSTILE]
]);

/**
 * `M[projection]`: the tiled CRS of a MapML projection name. `GLOBE` (the
 * port's deprecated alias) is OSMTILE. Unknown names give `undefined`.
 */
export function getTiledCrs(projection: string): TiledCrs | undefined {
  const name = projection.toUpperCase();
  return registry.get(name === 'GLOBE' ? 'OSMTILE' : name);
}

/**
 * The names custom projections were defined under: as given and in upper
 * case, the two keys MapML.js's `defineCustomProjection` sets on `M`.
 */
const customNames = new Set<string>();

/** Whether `name` names a projection defined with {@link defineCustomTiledCrs}. */
export function isCustomProjection(name: string): boolean {
  return customNames.has(name);
}

/**
 * Define a custom TCRS from MapML.js's JSON template (`projection`,
 * `proj4string`, `origin`, `resolutions`, `bounds`, optional `tilesize`)
 * and return its name. Ports MapML.js `defineCustomProjection`
 * (`src/mapml-viewer.js`): the same errors, and a name already defined
 * (in any case) returns that name in upper case without redefining it.
 * As in MapML.js, the gcrs axes' range is the OSMTILE bounds unprojected
 * in the custom CRS.
 */
export function defineCustomTiledCrs(jsonTemplate: string): string {
  const t = JSON.parse(jsonTemplate) as {
    projection?: string;
    proj4string?: string;
    origin?: [number, number];
    resolutions?: number[];
    bounds?: [[number, number], [number, number]];
    tilesize?: number;
  };
  if (
    t === undefined ||
    t === null ||
    !t.proj4string ||
    !t.projection ||
    !t.resolutions ||
    !t.origin ||
    !t.bounds
  ) {
    throw new Error('Incomplete TCRS Definition');
  }
  if (t.projection.indexOf(':') >= 0) {
    throw new Error('":" is not permitted in projection name');
  }
  const upper = t.projection.toUpperCase();
  if (registry.has(upper)) return upper;
  const [a, b] = t.bounds;
  const crs = createTiledCrs({
    name: t.projection,
    code: t.projection,
    proj4: t.proj4string,
    origin: [t.origin[0], t.origin[1]],
    // Leaflet's bounds(): the box around the two corners, in any order.
    bounds: {
      min: [Math.min(a[0], b[0]), Math.min(a[1], b[1])],
      max: [Math.max(a[0], b[0]), Math.max(a[1], b[1])]
    },
    resolutions: t.resolutions,
    tileSize: [256, 512, 1024, 2048, 4096].includes(t.tilesize as number)
      ? (t.tilesize as number)
      : TILE_SIZE,
    gcrsFrom: () => OSMTILE.bounds
  });
  registry.set(upper, crs);
  customNames.add(t.projection);
  customNames.add(upper);
  return t.projection;
}

/** {@link getTiledCrs}, falling back to OSMTILE (`M.FALLBACK_PROJECTION`). */
export function tiledCrs(projection: string): TiledCrs {
  return getTiledCrs(projection) ?? OSMTILE;
}

/**
 * The zoom level of `to` whose scale is nearest that of `from` at `zoom`,
 * so that a projection change keeps the scale rather than the zoom number
 * (which means a different scale in each CRS). Nearest is by ratio of the
 * resolutions in metres per pixel (scale is multiplicative), the coarser
 * level on a tie; a degree of a geographic CRS counts as 2π·6378137/360 m,
 * as OpenLayers' EPSG:4326 does. Ports MapML.js `Util.nearestScaleZoom`.
 */
export function nearestScaleZoom(from: string, zoom: number, to: string): number {
  const metresPerUnit = (crs: TiledCrs): number =>
    /\+proj=(longlat|latlong|lonlat|latlon)\b/.test(crs.proj4) ? (2 * Math.PI * 6378137) / 360 : 1;
  const fromCrs = tiledCrs(from);
  const toCrs = tiledCrs(to);
  const level = Math.max(0, Math.min(fromCrs.resolutions.length - 1, Math.round(zoom)));
  const target = fromCrs.resolutions[level]! * metresPerUnit(fromCrs);
  const distance = (i: number): number =>
    Math.abs(Math.log((toCrs.resolutions[i]! * metresPerUnit(toCrs)) / target));
  let best = 0;
  for (let i = 1; i < toCrs.resolutions.length; i++) {
    if (distance(i) < distance(best)) best = i;
  }
  return best;
}
