/**
 * Stylesheet for the link preview, {@link MapLibreRenderer}'s
 * `.mapml-link-preview` toast, ported from MapML.js's `mapml.css` (with
 * the font it inherits there from `.leaflet-container`).
 */
export const linkPreviewCss = /* css */ `
.mapml-link-preview {
  position: absolute;
  left: 0;
  bottom: 0;
  background-color: rgb(222, 225, 230);
  border-radius: 0 5px 0 0;
  z-index: 1050;
  max-width: 60%;
  pointer-events: none;
  font: 12px/1.5 'Helvetica Neue', Arial, Helvetica, sans-serif;
}

.mapml-link-preview > p {
  margin: 3px 5px 2px 3px;
  color: rgb(60, 64, 67);
  text-overflow: ellipsis;
  overflow-x: hidden;
  white-space: nowrap;
}
`;
