/**
 * Pure model for `<map-feature>` geometry: parsing `<map-coordinates>` text
 * into typed shapes, and converting those shapes to GeoJSON (WGS84 lon/lat)
 * or to a PCRS bounding box.
 *
 * The renderer consumes only GeoJSON in GCRS (`[lon, lat]`), because that's
 * what MapLibre expects for a `geojson` source. The PCRS bbox is used by
 * `<map-feature>.extent` and by the owning `<map-layer>` to union in
 * feature-derived bounds when computing its own extent — matching MapML.js
 * where `MapFeatureLayer` contributes to `<map-layer>.extent` via
 * `_calculateBounds()`.
 *
 * v1 support:
 *   - Coordinate systems: `gcrs`, `pcrs`, and the zoom-scaled `tcrs` /
 *     `tilematrix`, in any MapML CRS.
 *   - Geometry types: `<map-point>`, `<map-linestring>`, `<map-polygon>`,
 *     `<map-multipoint>`, `<map-multilinestring>`, `<map-multipolygon>`.
 *   - Inner rings (holes) on polygons — each `<map-coordinates>` after
 *     the first inside a `<map-polygon>` becomes a hole ring.
 *
 * Deliberately out of scope: `<map-geometrycollection>` — deferred.
 */

import {
  gcrsToPcrs,
  pcrsToGcrs,
  pcrsToTcrs,
  projectionTileSize,
  tcrsToPcrs,
  tilematrixToPcrs,
  type AnyProjection,
  type PcrsBounds
} from './crs';

/**
 * Coordinate systems of `<map-feature>` geometry. `tcrs` and
 * `tilematrix` are scaled by a zoom (the feature's native zoom).
 */
export type FeatureCS = 'gcrs' | 'pcrs' | 'tcrs' | 'tilematrix';

export interface FeaturePointShape {
  kind: 'Point';
  coordinates: [number, number];
}

export interface FeatureLineStringShape {
  kind: 'LineString';
  coordinates: [number, number][];
}

export interface FeaturePolygonShape {
  kind: 'Polygon';
  /**
   * Ring array in GeoJSON order: `coordinates[0]` is the outer ring,
   * `coordinates[1..]` are inner rings (holes). Each ring is closed
   * (its first and last coordinate are identical).
   */
  coordinates: [number, number][][];
}

/**
 * All points of a `<map-multipoint>`, flattened across any
 * `<map-coordinates>` children (matches MapML.js's
 * `<map-multipoint>` semantics: one point per `x y` pair).
 */
export interface FeatureMultiPointShape {
  kind: 'MultiPoint';
  coordinates: [number, number][];
}

/**
 * One line per `<map-coordinates>` child of `<map-multilinestring>`.
 */
export interface FeatureMultiLineStringShape {
  kind: 'MultiLineString';
  coordinates: [number, number][][];
}

/**
 * One polygon per `<map-polygon>` child of `<map-multipolygon>`. Each
 * polygon carries its rings in GeoJSON order (`[outer, hole1, hole2, …]`),
 * so holes-in-multi-polygon are supported the same way as
 * holes-in-polygon.
 */
export interface FeatureMultiPolygonShape {
  kind: 'MultiPolygon';
  coordinates: [number, number][][][];
}

export type FeatureShape =
  | FeaturePointShape
  | FeatureLineStringShape
  | FeaturePolygonShape
  | FeatureMultiPointShape
  | FeatureMultiLineStringShape
  | FeatureMultiPolygonShape;

/**
 * Normalise an author-supplied `cs` string. Returns `null` for unknown
 * values (`tcrs`, `tilematrix`, misspellings) so the caller can fall
 * back to a `<map-meta name="cs">` or the ultimate `gcrs` default,
 * matching MapML.js's `_getFallbackCS()`.
 */
export function parseGeometryCS(raw: string | null | undefined): 'gcrs' | 'pcrs' | null {
  if (raw === null || raw === undefined) return null;
  const v = raw.trim().toLowerCase();
  if (v === 'gcrs' || v === 'pcrs') return v;
  return null;
}

/**
 * {@link parseGeometryCS} plus the zoom-scaled `tcrs` and `tilematrix`
 * that MapML.js's `Util.pointToPCRSPoint` accepts — for a rendered
 * `<map-feature>`, which knows its native zoom.
 */
export function parseFeatureCS(raw: string | null | undefined): FeatureCS | null {
  const v = raw?.trim().toLowerCase();
  return v === 'tcrs' || v === 'tilematrix' ? v : parseGeometryCS(raw);
}

/**
 * Parse the text content of a `<map-coordinates>` element into a flat
 * `[x, y, x, y, …]` list of finite numbers. MapML.js's rules apply:
 * inline markup (e.g. `<map-span>` annotations) is stripped, and any
 * combination of whitespace and commas separates values.
 */
export function parseCoordinatesText(text: string): number[] {
  return text
    .replace(/<[^>]+>/g, ' ')
    .replace(/[,\r\n\t]+/g, ' ')
    .trim()
    .split(/\s+/)
    .filter((s) => s !== '')
    .map(Number)
    .filter((n) => Number.isFinite(n));
}

function pairs(flat: readonly number[]): [number, number][] {
  const out: [number, number][] = [];
  for (let i = 0; i + 1 < flat.length; i += 2) {
    out.push([flat[i]!, flat[i + 1]!]);
  }
  return out;
}

/**
 * Extract every ring from a `<map-polygon>` element. Each child
 * `<map-coordinates>` contributes one ring in document order:
 * the first ring is the polygon's outer boundary, and any subsequent
 * rings are inner rings (holes) — matching MapML.js's
 * `path.js#_coordinateToArrays` behaviour (first ring drives
 * `_parts[0].rings[0]`, further rings become `_parts[0].rings[i]`).
 *
 * Each ring is auto-closed per the GeoJSON spec (the polygon spec
 * requires each ring's first and last coordinate be identical).
 * Rings with fewer than three vertex pairs are skipped.
 */
function ringsFromPolygonElement(polygon: Element): [number, number][][] {
  const rings: [number, number][][] = [];
  for (const c of polygon.querySelectorAll('map-coordinates')) {
    const flat = parseCoordinatesText(c.textContent ?? '');
    if (flat.length < 6) continue;
    const ring = pairs(flat);
    const first = ring[0]!;
    const last = ring[ring.length - 1]!;
    if (first[0] !== last[0] || first[1] !== last[1]) ring.push([first[0], first[1]]);
    rings.push(ring);
  }
  return rings;
}

/**
 * Walk the children of a `<map-geometry>` element and produce the list
 * of typed {@link FeatureShape}s it contains. Recognised element names:
 * `<map-point>`, `<map-linestring>`, `<map-polygon>`,
 * `<map-multipoint>`, `<map-multilinestring>`, `<map-multipolygon>`.
 * All other children are ignored (with no warning — the author may
 * legitimately have commented-out or unsupported geometry mixed in).
 *
 * Structural conventions (match MapML.js's `Util.geojson2mapml` +
 * `path.js`): `<map-multipoint>` groups all points into (usually one)
 * `<map-coordinates>` child, `<map-multilinestring>` uses one
 * `<map-coordinates>` per line, `<map-multipolygon>` uses one
 * `<map-polygon>` per polygon (each with its own `<map-coordinates>`).
 */
export function shapesFromGeometry(geometry: Element): FeatureShape[] {
  return shapesFromGeometryWithSource(geometry).map((entry) => entry.shape);
}

/**
 * Same DOM walk as {@link shapesFromGeometry}, but also returns the
 * source element each shape came from and (when present) the nearest
 * enclosing `<map-a>` wrapper.
 *
 * The `source` element is the direct-descendant `<map-polygon>` /
 * `<map-linestring>` / `<map-multipoint>` / … under `<map-geometry>` —
 * the node MapML.js authors historically decorate with a `class`
 * attribute for CSS styling (Leaflet renders one SVG element per
 * geometry child and copies the `class` onto it). `<map-style>`
 * compilation reads the class from these source elements so a
 * `<map-polygon class="a">` under a `<map-feature>` picks up
 * `.a { fill: red }` rules, matching MapML.js behaviour.
 *
 * `<map-a>` / `<map-span>` wrappers around a shape are unwrapped —
 * the shape is emitted at the same "slot" as if the wrapper wasn't
 * there. When the shape sits under one or more `<map-a>` wrappers,
 * the *innermost* one is returned as `linkWrapper` so callers can
 * lift its `href` / `target` / `type` / `inplace` attributes into the
 * emitted GeoJSON feature's properties (MapML.js's `_convertWrappers`
 * behaves similarly — the innermost `<map-a>` on the wrapper stack
 * wins, as it does for each path MapML.js draws per shape). A
 * `<map-a>` run inside `<map-coordinates>` is not a wrapper of the
 * shape: see {@link featureIndexStops}.
 *
 * `<map-geometrycollection>` is also unwrapped so a `<map-a>` around
 * a whole collection lifts a link onto every emitted shape inside it,
 * and shapes at the top level of a collection contribute individually.
 */
export function shapesFromGeometryWithSource(
  geometry: Element
): Array<{ shape: FeatureShape; source: Element; linkWrapper: Element | null }> {
  const out: Array<{ shape: FeatureShape; source: Element; linkWrapper: Element | null }> = [];
  visitShapeCandidates(geometry, null, out);
  return out;
}

/**
 * Walk `parent`'s children collecting recognised shape elements.
 * When a child is a `<map-a>` / `<map-span>` / `<map-geometrycollection>`
 * wrapper, recurse into it — inheriting the innermost `<map-a>` seen
 * along the way as the shape's `linkWrapper`. All other unrecognised
 * elements (comments, whitespace-only text, unknown tags) are
 * silently skipped, matching MapML.js's forgiving `_convertMarkup`
 * pass.
 */
function visitShapeCandidates(
  parent: Element,
  currentLink: Element | null,
  out: Array<{ shape: FeatureShape; source: Element; linkWrapper: Element | null }>
): void {
  for (const child of Array.from(parent.children)) {
    const tag = child.tagName.toLowerCase();
    if (tag === 'map-a') {
      // Innermost wrapper wins — MapML.js semantics for nested
      // `<map-a>` (parent + inplace child in `linkTypes.html`).
      visitShapeCandidates(child, child, out);
      continue;
    }
    if (tag === 'map-span' || tag === 'map-geometrycollection') {
      // `<map-span>` is a class-annotation wrapper; `<map-geometrycollection>`
      // groups sibling geometries. Neither carries a link on its own,
      // so `currentLink` is preserved through the recursion.
      visitShapeCandidates(child, currentLink, out);
      continue;
    }
    const shape = shapeFromElement(child, tag);
    if (shape !== null) {
      out.push({ shape, source: child, linkWrapper: currentLink });
    }
  }
}

/**
 * Turn a single recognised shape element (`<map-point>`,
 * `<map-linestring>`, `<map-polygon>`, or one of the `<map-multi*>`
 * flavours) into a typed {@link FeatureShape}. Returns `null` for
 * unrecognised tags or degenerate coordinate sets (fewer vertices
 * than the type requires).
 */
function shapeFromElement(el: Element, tag: string): FeatureShape | null {
  if (tag === 'map-point' || tag === 'map-linestring' || tag === 'map-multipoint') {
    const flat: number[] = [];
    for (const c of el.querySelectorAll('map-coordinates')) {
      flat.push(...parseCoordinatesText(c.textContent ?? ''));
    }
    if (flat.length < 2) return null;
    if (tag === 'map-point') {
      return { kind: 'Point', coordinates: [flat[0]!, flat[1]!] };
    }
    if (tag === 'map-linestring') {
      if (flat.length < 4) return null;
      return { kind: 'LineString', coordinates: pairs(flat) };
    }
    // map-multipoint: every pair is one point.
    return { kind: 'MultiPoint', coordinates: pairs(flat) };
  }
  if (tag === 'map-polygon') {
    const rings = ringsFromPolygonElement(el);
    if (rings.length === 0) return null;
    return { kind: 'Polygon', coordinates: rings };
  }
  if (tag === 'map-multilinestring') {
    const lines: [number, number][][] = [];
    for (const c of el.querySelectorAll('map-coordinates')) {
      const line = pairs(parseCoordinatesText(c.textContent ?? ''));
      if (line.length >= 2) lines.push(line);
    }
    if (lines.length === 0) return null;
    return { kind: 'MultiLineString', coordinates: lines };
  }
  if (tag === 'map-multipolygon') {
    const polys: [number, number][][][] = [];
    // Iterate direct <map-polygon> children so nested geometries in
    // future authoring don't collapse into this one.
    for (const poly of Array.from(el.children)) {
      if (poly.tagName.toLowerCase() !== 'map-polygon') continue;
      const rings = ringsFromPolygonElement(poly);
      if (rings.length === 0) continue;
      polys.push(rings);
    }
    if (polys.length === 0) return null;
    return { kind: 'MultiPolygon', coordinates: polys };
  }
  return null;
}

/**
 * A non-GCRS pair → PCRS, ported from MapML.js `Util.pointToPCRSPoint`
 * (`tcrs` / `tilematrix` are at `zoom`).
 */
function toPcrsPoint(
  x: number,
  y: number,
  cs: Exclude<FeatureCS, 'gcrs'>,
  projection: AnyProjection,
  zoom: number
): [number, number] {
  if (cs === 'tcrs') return tcrsToPcrs(projection, x, y, zoom);
  if (cs === 'tilematrix') return tilematrixToPcrs(projection, x, y, zoom);
  return [x, y];
}

/** Convert a source-CS pair to GCRS `[lon, lat]` in `projection`. */
export function toGcrsPoint(
  x: number,
  y: number,
  cs: FeatureCS,
  projection: AnyProjection,
  zoom = 0
): [number, number] {
  if (cs === 'gcrs') return [x, y];
  const [px, py] = toPcrsPoint(x, y, cs, projection, zoom);
  return pcrsToGcrs(projection, px, py);
}

/**
 * Convert typed shapes to GeoJSON `Feature`s in GCRS (WGS84 lon/lat).
 * The `properties` argument is copied verbatim onto every emitted
 * feature (typically `{ caption }` from `<map-featurecaption>`).
 * `zoom` scales `tcrs` / `tilematrix` coordinates.
 */
export function shapesToGeoJson(
  shapes: readonly FeatureShape[],
  cs: FeatureCS,
  projection: AnyProjection,
  properties: Record<string, unknown> = {},
  zoom = 0
): GeoJSON.Feature[] {
  const out: GeoJSON.Feature[] = [];
  for (const s of shapes) {
    if (s.kind === 'Point') {
      const [x, y] = s.coordinates;
      out.push({
        type: 'Feature',
        geometry: { type: 'Point', coordinates: toGcrsPoint(x, y, cs, projection, zoom) },
        properties: { ...properties }
      });
    } else if (s.kind === 'LineString') {
      out.push({
        type: 'Feature',
        geometry: {
          type: 'LineString',
          coordinates: s.coordinates.map(([x, y]) => toGcrsPoint(x, y, cs, projection, zoom))
        },
        properties: { ...properties }
      });
    } else if (s.kind === 'Polygon') {
      out.push({
        type: 'Feature',
        geometry: {
          type: 'Polygon',
          coordinates: s.coordinates.map((ring) =>
            ring.map(([x, y]) => toGcrsPoint(x, y, cs, projection, zoom))
          )
        },
        properties: { ...properties }
      });
    } else if (s.kind === 'MultiPoint') {
      out.push({
        type: 'Feature',
        geometry: {
          type: 'MultiPoint',
          coordinates: s.coordinates.map(([x, y]) => toGcrsPoint(x, y, cs, projection, zoom))
        },
        properties: { ...properties }
      });
    } else if (s.kind === 'MultiLineString') {
      out.push({
        type: 'Feature',
        geometry: {
          type: 'MultiLineString',
          coordinates: s.coordinates.map((line) =>
            line.map(([x, y]) => toGcrsPoint(x, y, cs, projection, zoom))
          )
        },
        properties: { ...properties }
      });
    } else {
      out.push({
        type: 'Feature',
        geometry: {
          type: 'MultiPolygon',
          coordinates: s.coordinates.map((poly) =>
            poly.map((ring) => ring.map(([x, y]) => toGcrsPoint(x, y, cs, projection, zoom)))
          )
        },
        properties: { ...properties }
      });
    }
  }
  return out;
}

/**
 * One contiguous boundary run of a shape, split at `<map-span>`
 * boundaries. `className` is the span's `class` attribute for a
 * span-wrapped run, or `null` for a bare-text run (which inherits the
 * geometry's own class). Coordinates are in GCRS `[lon, lat]`.
 */
export interface BoundarySegment {
  coordinates: [number, number][];
  className: string | null;
}

/** Whether any `<map-coordinates>` inside `el` wraps a `<map-span>`. */
export function elementHasCoordinateSpans(el: Element): boolean {
  return el.querySelector('map-coordinates map-span') !== null;
}

/**
 * Extract a shape's boundary as an ordered list of {@link BoundarySegment}s,
 * preserving the `<map-span class="…">` annotations GeoServer uses to
 * mark tile-clip edges. Each `<map-coordinates>` under `el` is walked
 * child-node by child-node: text runs become `className: null`
 * segments (real boundary, stroked with the geometry's own class),
 * `<map-span>` runs become `className: <span class>` segments (a
 * `.bbox { display:none }` rule then hides the tile-edge runs).
 *
 * MapLibre can't per-segment-style one geometry's outline, so the
 * caller emits these as separate `LineString` features for the stroke
 * while the polygon geometry itself carries only the fill. Returns
 * `[]` when `el` has no spans (caller keeps the whole-geometry stroke).
 *
 * A span wraps just the segments it styles, so a text run is joined to
 * its neighbouring spans: it starts at the last vertex of the span
 * before it and ends at the first vertex of the span after it. In a
 * `closed` shape (a polygon ring) the runs wrap around. Ported from
 * MapML.js `features/path.js` `_generateOutlinePoints`.
 */
export function boundarySegmentsFromElement(
  el: Element,
  cs: FeatureCS,
  projection: AnyProjection,
  zoom = 0,
  closed = true
): BoundarySegment[] {
  const segments: BoundarySegment[] = [];
  const toGcrs = (pts: [number, number][], className: string | null): void => {
    if (pts.length < 2) return;
    segments.push({
      coordinates: pts.map(([x, y]) => toGcrsPoint(x, y, cs, projection, zoom)),
      className
    });
  };
  for (const coords of el.querySelectorAll('map-coordinates')) {
    // The runs in document order: text (`className: null`) and spans.
    const runs: { pts: [number, number][]; className: string | null }[] = [];
    let textRun = '';
    const flushText = (): void => {
      const pts = pairs(parseCoordinatesText(textRun));
      textRun = '';
      if (pts.length > 0) runs.push({ pts, className: null });
    };
    for (const node of Array.from(coords.childNodes)) {
      if (node.nodeType === node.ELEMENT_NODE) {
        const elNode = node as Element;
        if (elNode.tagName.toLowerCase() === 'map-span') {
          // A span run is its own segment; flush the text accumulated
          // before it so document order is preserved.
          flushText();
          const pts = pairs(parseCoordinatesText(elNode.textContent ?? ''));
          if (pts.length > 0) {
            runs.push({ pts, className: elNode.getAttribute('class') });
          }
          continue;
        }
      }
      textRun += ` ${node.textContent ?? ''}`;
    }
    flushText();
    const neighbour = (i: number): (typeof runs)[number] | undefined =>
      closed ? runs[(i + runs.length) % runs.length] : runs[i];
    runs.forEach((run, i) => {
      if (run.className !== null) {
        toGcrs(run.pts, run.className);
        return;
      }
      const prev = neighbour(i - 1);
      const next = neighbour(i + 1);
      const before =
        prev && prev !== run && prev.className !== null ? prev.pts[prev.pts.length - 1] : undefined;
      const after = next && next !== run && next.className !== null ? next.pts[0] : undefined;
      toGcrs([...(before ? [before] : []), ...run.pts, ...(after ? [after] : [])], null);
    });
  }
  return segments;
}

/**
 * Compute the PCRS bounding box that covers every coordinate in the
 * given shapes. Returns `null` when no coordinates were seen.
 *
 * Ported from MapML.js `<map-feature>` `_memoizeExtent`: the box is
 * taken in the source `cs` and its two corners are converted with
 * `Util.boundsToPCRSBounds` (`zoom` scales `tcrs` / `tilematrix`).
 * For `gcrs` that is the projected lon/lat box — the vertices' own
 * PCRS box in OSMTILE and WGS84, where x depends on lon alone and y
 * on lat alone, but not in a conic or polar CRS (CBMTILE, APSTILE).
 */
export function shapesToPcrsBounds(
  shapes: readonly FeatureShape[],
  cs: FeatureCS,
  projection: AnyProjection,
  zoom = 0
): PcrsBounds | null {
  const box = boxBuilder();
  forEachVertex(shapes, box.visit);
  const { minX, minY, maxX, maxY } = box;
  if (!Number.isFinite(minX)) return null;
  if (cs === 'pcrs') return { min: [minX, minY], max: [maxX, maxY] };
  const [ax, ay] =
    cs === 'gcrs' ? gcrsToPcrs(projection, minX, minY) : toPcrsPoint(minX, minY, cs, projection, zoom);
  const [bx, by] =
    cs === 'gcrs' ? gcrsToPcrs(projection, maxX, maxY) : toPcrsPoint(maxX, maxY, cs, projection, zoom);
  return {
    min: [Math.min(ax, bx), Math.min(ay, by)],
    max: [Math.max(ax, bx), Math.max(ay, by)]
  };
}

/**
 * The PCRS bounding box of the shapes' vertices, each converted to PCRS
 * before it is boxed. Returns `null` when no coordinates were seen.
 *
 * Ported from MapML.js `features/path.js` `_coordinateToArrays`, which
 * builds each rendered path's `_bounds` this way; the feature index
 * overlay tests those against its reticle. Unlike
 * {@link shapesToPcrsBounds} (the feature's `.extent`), it is the true
 * box of the drawn shape in a conic or polar CRS, and a lone point
 * stays a point.
 */
export function shapesToVertexPcrsBounds(
  shapes: readonly FeatureShape[],
  cs: FeatureCS,
  projection: AnyProjection,
  zoom = 0
): PcrsBounds | null {
  const box = boxBuilder();
  forEachVertex(shapes, (x, y) => {
    if (cs === 'pcrs') box.visit(x, y);
    else if (cs === 'gcrs') box.visit(...gcrsToPcrs(projection, x, y));
    else box.visit(...toPcrsPoint(x, y, cs, projection, zoom));
  });
  const { minX, minY, maxX, maxY } = box;
  if (!Number.isFinite(minX)) return null;
  return { min: [minX, minY], max: [maxX, maxY] };
}

function boxBuilder() {
  const box = {
    minX: Infinity,
    minY: Infinity,
    maxX: -Infinity,
    maxY: -Infinity,
    visit: (x: number, y: number): void => {
      if (x < box.minX) box.minX = x;
      if (y < box.minY) box.minY = y;
      if (x > box.maxX) box.maxX = x;
      if (y > box.maxY) box.maxY = y;
    }
  };
  return box;
}

function forEachVertex(
  shapes: readonly FeatureShape[],
  visit: (x: number, y: number) => void
): void {
  for (const s of shapes) {
    if (s.kind === 'Point') {
      const [x, y] = s.coordinates;
      visit(x, y);
    } else if (s.kind === 'LineString' || s.kind === 'MultiPoint') {
      for (const [x, y] of s.coordinates) visit(x, y);
    } else if (s.kind === 'MultiLineString') {
      for (const line of s.coordinates) for (const [x, y] of line) visit(x, y);
    } else if (s.kind === 'Polygon') {
      for (const ring of s.coordinates) for (const [x, y] of ring) visit(x, y);
    } else {
      for (const poly of s.coordinates)
        for (const ring of poly) for (const [x, y] of ring) visit(x, y);
    }
  }
}

/**
 * Grow a lone point's (empty) PCRS box to a tile-sized box centred on
 * the point, at `zoom`.
 *
 * Ported from MapML.js `map-feature.js` `_memoizeExtent`, which offsets
 * the point by half a tile in TCRS before converting back, so a point
 * feature's `.extent` — and the layer bounds the debug overlay draws
 * from it — is a tile rather than a degenerate rectangle.
 */
export function pointBoundsToTileBounds(
  bounds: PcrsBounds,
  zoom: number,
  projection: AnyProjection = 'OSMTILE'
): PcrsBounds {
  const [x, y] = bounds.min;
  const tcrs = pcrsToTcrs(projection, x, y, zoom);
  const half = projectionTileSize(projection) / 2;
  // TCRS y grows southward, so subtracting it gives the northern edge.
  const [minX, maxY] = tcrsToPcrs(
    projection,
    tcrs.horizontal - half,
    tcrs.vertical - half,
    zoom
  );
  const [maxX, minY] = tcrsToPcrs(
    projection,
    tcrs.horizontal + half,
    tcrs.vertical + half,
    zoom
  );
  return { min: [minX, minY], max: [maxX, maxY] };
}

/**
 * A keyboard focus stop of a feature besides the feature itself: a
 * `<map-a>` (or `<map-span tabindex>`) run inside `<map-coordinates>`,
 * or a `<map-geometrycollection>` member wrapped in a `<map-a>` of its
 * own. MapML.js draws each as its own SVG path and indexes it when it
 * has a `tabindex` (features/geometry.js `updateInteraction`).
 */
export interface FeatureIndexPart {
  /** PCRS centre of the part's coordinates' bounds. */
  center: [number, number];
  /** The part's coordinates, in PCRS. */
  points: [number, number][];
  /** The `<map-a href>` the part links with, if any. */
  link: Element | null;
  /** The part's own `aria-label`, if any. */
  label: string | null;
}

/** Where a feature sits in the feature index, and its focusable parts. */
export interface FeatureIndexStops {
  /**
   * PCRS centre of the bounds of the feature's member shapes' own
   * bounds-centres (MapML.js geometry.js `getPCRSCenter`); `null` when
   * the geometry has no coordinates.
   */
  center: [number, number] | null;
  /** The `<map-a href>` the feature as a whole links with, if any. */
  link: Element | null;
  /** Focusable sub-parts, in MapML.js's index insertion order. */
  parts: FeatureIndexPart[];
}

/** MapML.js MapFeatureLayer `_geometryToLayer`: the shapes drawn as paths. */
const INDEX_PATH_SELECTOR =
  'map-polygon, map-linestring, map-multilinestring, map-point, map-multipoint';

/**
 * Ported from MapML.js MapFeatureLayer `_getGeometryParents`: the
 * wrappers of a shape, innermost first, up to (not including)
 * `<map-geometry>`, skipping `<map-multipolygon>` /
 * `<map-geometrycollection>`.
 */
function geometryParents(el: Element | null): Element[] {
  const elems: Element[] = [];
  for (let node = el; node !== null; node = node.parentElement) {
    const tag = node.tagName.toLowerCase();
    if (tag === 'map-geometry') break;
    if (tag !== 'map-multipolygon' && tag !== 'map-geometrycollection') elems.push(node);
  }
  return elems;
}

/** The link of a wrapper list, as MapML.js path.js `_convertWrappers` picks it. */
function wrapperLink(elems: readonly Element[]): Element | null {
  for (const el of elems) {
    if (el.tagName.toLowerCase() === 'map-a' && el.getAttribute('href')) return el;
  }
  return null;
}

/**
 * The feature index stops of a `<map-geometry>`, ported from MapML.js:
 * MapFeatureLayer `_geometryToLayer` (one path per shape), path.js
 * `_convertMarkup` (a shape whose parent is a `<map-a>` below a
 * collection gets `tabindex=0`) and `_coordinateToArrays` (each element
 * inside `<map-coordinates>` is a sub-part, given `tabindex=0` when it
 * links), and geometry.js `getPCRSCenter` / `updateInteraction`.
 * Coordinates convert to PCRS as `Util.pointToPCRSPoint` does.
 */
export function featureIndexStops(
  geometry: Element,
  cs: FeatureCS,
  projection: AnyProjection,
  zoom = 0
): FeatureIndexStops {
  const toPcrs = (x: number, y: number): [number, number] =>
    cs === 'gcrs' ? gcrsToPcrs(projection, x, y) : toPcrsPoint(x, y, cs, projection, zoom);
  const pointsOf = (el: Element): [number, number][] =>
    pairs(parseCoordinatesText(el.textContent ?? '')).map(([x, y]) => toPcrs(x, y));
  const centerOf = (points: readonly [number, number][]): [number, number] | null => {
    const box = boxBuilder();
    for (const [x, y] of points) box.visit(x, y);
    if (!Number.isFinite(box.minX)) return null;
    return [(box.minX + box.maxX) / 2, (box.minY + box.maxY) / 2];
  };

  const parts: FeatureIndexPart[] = [];
  const memberCenters: [number, number][] = [];
  const memberLinks: Array<Element | null> = [];
  for (const geo of geometry.querySelectorAll(INDEX_PATH_SELECTOR)) {
    const link = wrapperLink(geometryParents(geo.parentElement));
    const points: [number, number][] = [];
    for (const coords of geo.querySelectorAll('map-coordinates')) points.push(...pointsOf(coords));
    const center = centerOf(points);
    if (center === null) continue;
    memberCenters.push(center);
    memberLinks.push(link);
    // path.js `_convertMarkup`: an authored tabindex wins over the one a
    // collection member wrapped in its own `<map-a>` gets.
    const parent = geo.parentElement;
    const wrappedMember =
      link !== null &&
      parent?.tagName.toLowerCase() === 'map-a' &&
      parent.parentElement?.tagName.toLowerCase() !== 'map-geometry';
    if (geo.getAttribute('tabindex') ?? (wrappedMember ? '0' : null)) {
      parts.push({ center, points, link, label: geo.getAttribute('aria-label') });
    }
    // A multipoint's sub-parts become points of its own, not sub-paths.
    if (geo.tagName.toLowerCase() === 'map-multipoint') continue;
    for (const coords of geo.querySelectorAll('map-coordinates')) {
      parts.push(...coordinateSubParts(coords, pointsOf, centerOf));
    }
  }

  // geometry.js: a collection's wrappers give the group its link, but a
  // lone shape's own link wins.
  const collection =
    geometry.querySelector('map-multipolygon') ?? geometry.querySelector('map-geometrycollection');
  let link = collection !== null ? wrapperLink(geometryParents(collection.parentElement)) : null;
  if (memberLinks.length === 1 && memberLinks[0]) link = memberLinks[0];
  return { center: centerOf(memberCenters), link, parts };
}

/**
 * Ported from MapML.js path.js `_coordinateToArrays`: the elements
 * inside one `<map-coordinates>` (nested ones first, each list built by
 * `unshift`) that are focus stops. A run's link comes from its wrapper
 * chain, outermost first (`_convertWrappers(parents)`); its own
 * attributes, an authored `tabindex` among them, override.
 */
function coordinateSubParts(
  coords: Element,
  pointsOf: (el: Element) => [number, number][],
  centerOf: (points: readonly [number, number][]) => [number, number] | null
): FeatureIndexPart[] {
  const subParts: FeatureIndexPart[] = [];
  const visit = (el: Element, parents: Element[]): void => {
    for (const child of Array.from(el.children)) visit(child, parents.concat([child]));
    if (parents.length === 0) return;
    const points = pointsOf(el);
    const center = centerOf(points);
    if (center === null) return;
    const link = wrapperLink(parents);
    const tabindex = el.getAttribute('tabindex') ?? (link !== null ? '0' : null);
    if (!tabindex) return;
    subParts.unshift({ center, points, link, label: el.getAttribute('aria-label') });
  };
  visit(coords, []);
  return subParts;
}
