/**
 * MapML CRSs as MapLibre projections.
 *
 * OSMTILE is MapLibre's built-in `mercator`. Every other MapML CRS,
 * custom ones included, is registered once per page with
 * `maplibregl.addProjection` (MapLibre GL JS ≥ 6.15), under its EPSG code
 * ({@link mapLibreProjectionName}): proj4 for lng/lat ↔ CRS, and the quad
 * tile grid from `core/zoomScale.ts` {@link quadGrid}. The registry is
 * global and register-once, so every viewer on a page shares it.
 *
 * GeoJSON sources are tiled in MapLibre's workers, which need the same
 * converter: `projectionHandlerWorker.ts` is loaded into them once with
 * `importScriptInWorkers`, and {@link whenProjectionReady} resolves when
 * it has been.
 */
import * as maplibregl from 'maplibre-gl';
import projectionHandlerUrl from './projectionHandlerWorker.ts?worker&url';
import { tiledCrs } from '../core/projections';
import { quadGrid } from '../core/zoomScale';

/**
 * MapLibre's projection type for a MapML CRS: `mercator`, or the name it
 * is registered under: its EPSG code, or for a custom projection (whose
 * name MapML forbids a colon in, which MapLibre requires) `mapml:` and
 * its name.
 */
export function mapLibreProjectionName(projection: string): string {
  const crs = tiledCrs(projection);
  if (crs.name === 'OSMTILE') return 'mercator';
  return crs.code.includes(':') ? crs.code : `mapml:${crs.code}`;
}

let workersReady: Promise<void> | null = null;

/**
 * Load the proj4 projection handler into MapLibre's workers, once.
 * MapLibre `import()`s a script url ending in `.mjs`; any other url is
 * fetched and re-run from a `blob:` url, where the dev server's
 * root-relative module imports can't resolve — so the url is given a
 * `#.mjs` fragment, which `import()` ignores.
 */
function ensureWorkerHandler(): Promise<void> {
  workersReady ??= maplibregl
    .importScriptInWorkers(new URL(`${projectionHandlerUrl}#.mjs`, import.meta.url).href)
    .catch((err: unknown) => {
      workersReady = null;
      console.warn('MapML: could not load the projection handler into MapLibre workers', err);
    });
  return workersReady;
}

const registered = new Set<string>();

/**
 * Register a MapML CRS with MapLibre (idempotent) and return its MapLibre
 * projection name. OSMTILE needs no registration.
 */
export function ensureMapLibreProjection(projection: string): string {
  const name = mapLibreProjectionName(projection);
  if (name === 'mercator' || registered.has(name)) return name;
  const crs = tiledCrs(projection);
  const grid = quadGrid(projection);
  maplibregl.addProjection({
    name,
    definition: crs.proj4,
    projection: {
      forward: (p) => crs.project(p[0]!, p[1]!),
      // MapLibre stops at the edge of the answers where inverse gives
      // null; proj4 extrapolates past a CRS's world instead, so lng/lat
      // outside the globe count as no answer.
      inverse: (p) => {
        const [lon, lat] = crs.unproject(p[0]!, p[1]!);
        return Number.isFinite(lon) && Number.isFinite(lat) &&
          Math.abs(lon) <= 180 && Math.abs(lat) <= 90
          ? [lon, lat]
          : null;
      }
    },
    tileMatrixSet: { origin: grid.origin, extentAtZoom0: grid.extentAtZoom0 }
  });
  registered.add(name);
  return name;
}

/**
 * Resolves when a map in `projection` can load sources: immediately for
 * OSMTILE, after the workers' projection handler has loaded otherwise.
 */
export function whenProjectionReady(projection: string): Promise<void> {
  return mapLibreProjectionName(projection) === 'mercator'
    ? Promise.resolve()
    : ensureWorkerHandler();
}
