/**
 * Keep a MapLibre map on whole MapML zoom levels, as Leaflet's default
 * `zoomSnap: 1` keeps MapML.js: zoom buttons, keys, double-click, the
 * wheel, pinch and `fitBounds` all land on a level of the viewer's
 * projection.
 *
 * Where a MapML level is a whole MapLibre zoom (OSMTILE, WGS84, APSTILE
 * on a flat map; see `core/zoomScale.ts` {@link mapLibreZoomSnap}) the
 * map uses MapLibre's own `zoomSnap: 1`, which snaps every camera method
 * and gesture handler. Elsewhere — CBMTILE, whose levels are
 * cartographic scales unevenly spaced on MapLibre's scale, and a globe,
 * whose MapML zoom depends on the latitude (`globeToFlatZoom`) — the
 * map's camera methods are wrapped to snap through the {@link ZoomScale}
 * instead: `jumpTo` / `easeTo` / `flyTo` to the nearest level and
 * `cameraForBounds` (so `fitBounds`) down a level.
 *
 * The wheel's target is snapped here in every case, to the next level in
 * the wheel's direction, as Leaflet's scroll-wheel zoom (and MapLibre's,
 * under `zoomSnap`) does. MapLibre's own snap measures the direction from
 * the level nearest the current zoom, so at a minimum that isn't a whole
 * level (a map taller than the world at zoom 0) a zoom-out read as a
 * zoom-in.
 *
 * A gesture that ends between levels without going through a camera
 * method — a pinch released without inertia, a trackpad, or a pan across
 * the globe's blend into flat Mercator — settles on a level after its
 * `zoomend`: the nearest, as Leaflet's touch zoom does on `touchend`, or
 * the next one in the wheel's direction. Until that settling animation
 * starts, {@link ZoomSnap.isSettling} is true, so the viewer can leave
 * the in-between view out of its history.
 *
 * `zoomIn` / `zoomOut` step one level from the level the map is zooming
 * to, so repeated clicks of a zoom button add up as they do in Leaflet.
 */
import type * as maplibregl from 'maplibre-gl';

/** Leaflet's zoom animation lasts 0.25 s. */
const SETTLE_DURATION = 250;

const EPSILON = 1e-9;
/** Tolerance for "already on a whole MapML level". */
const LEVEL_EPSILON = 1e-6;

/** How the map's zoom reads as a MapML zoom (the renderer's conversions). */
export interface ZoomScale {
  /** MapLibre zoom `m` → MapML zoom, with the centre at `lat` (default: the map's). */
  toMapml(m: number, lat?: number): number;
  /** MapML zoom `z` → MapLibre zoom, with the centre at `lat` (default: the map's). */
  toNative(z: number, lat?: number): number;
  /** The map's zoom range, as MapML zooms. */
  range(): { min: number; max: number };
  /**
   * The lowest MapLibre zoom the map can be at where it is: MapLibre
   * raises a flat map's until the world fills the viewport.
   */
  minNative(): number;
  /** Whether MapLibre's own `zoomSnap: 1` lands on whole MapML levels. */
  uniform(): boolean;
}

export interface ZoomSnap {
  /** True from a between-levels `zoomend` until its settling animation starts. */
  isSettling(): boolean;
  /**
   * Re-read {@link ZoomScale.uniform} after a projection or view change.
   * The listeners stay where they are, so they still run first.
   */
  update(): void;
  destroy(): void;
}

type CameraOptionsWithZoom = { zoom?: number; center?: maplibregl.LngLatLike };

/** The whole MapML level `z` snaps to: nearest, or next in `direction`. */
function level(z: number, direction: number): number {
  return direction > 0
    ? Math.ceil(z - LEVEL_EPSILON)
    : direction < 0
      ? Math.floor(z + LEVEL_EPSILON)
      : Math.round(z);
}

function isWholeLevel(z: number): boolean {
  return Math.abs(z - Math.round(z)) < LEVEL_EPSILON;
}

function latitudeOf(center: maplibregl.LngLatLike | undefined): number | undefined {
  if (center === undefined) return undefined;
  if (Array.isArray(center)) return center[1];
  return (center as { lat: number }).lat;
}

/**
 * Snap `map` to whole MapML levels. Call right after the map is
 * constructed with `zoomSnap: scale.uniform() ? 1 : 0`, before any other
 * `zoomend` listener is added, so {@link ZoomSnap.isSettling} is current
 * when the others run.
 */
export function installZoomSnap(map: maplibregl.Map, scale: ZoomScale): ZoomSnap {
  const restoreSteps = snapZoomSteps(map, scale);
  const restoreWheel = snapWheel(map, scale);
  const cameraSnap = (): (() => void) =>
    scale.uniform() ? () => {} : snapCameraMethods(map, scale);
  let restoreCamera = cameraSnap();

  let settling = false;
  let timer: ReturnType<typeof setTimeout> | undefined;
  // The scroll handler's events carry no wheel event, so the gesture and
  // its direction are read off the handler and the wheel events.
  let wheelGesture = false;
  let wheelDirection = 0;
  const onWheel = (e: WheelEvent): void => {
    if (e.deltaY) wheelDirection = -Math.sign(e.deltaY);
  };
  const container = map.getCanvasContainer();
  container.addEventListener('wheel', onWheel, { capture: true, passive: true });

  const onZoomStart = (): void => {
    wheelGesture = map.scrollZoom.isActive();
  };
  const onZoomEnd = (): void => {
    if (settling) return;
    const z = scale.toMapml(map.getZoom());
    if (isWholeLevel(z)) return;
    const { min, max } = scale.range();
    const targetLevel = level(z, wheelGesture ? wheelDirection : 0);
    const target = scale.toNative(targetLevel);
    // MapLibre raises the zoom until the world fills the viewport; a
    // level below that can't be reached, so the view stays where it is.
    if (
      targetLevel < min - LEVEL_EPSILON ||
      targetLevel > max + LEVEL_EPSILON ||
      target < scale.minNative() - EPSILON
    ) {
      return;
    }
    settling = true;
    // After this zoomend's moveend: easing from inside the gesture's own
    // event dispatch would interleave the two moves' events.
    timer = setTimeout(() => {
      timer = undefined;
      settling = false;
      // A new gesture or animation has taken over; its end settles it.
      if (map.isMoving()) return;
      map.easeTo({ zoom: target, duration: SETTLE_DURATION });
    }, 0);
  };
  map.on('zoomstart', onZoomStart);
  map.on('zoomend', onZoomEnd);

  return {
    isSettling: () => settling,
    update: () => {
      restoreCamera();
      map.setZoomSnap(scale.uniform() ? 1 : 0);
      restoreCamera = cameraSnap();
    },
    destroy: () => {
      map.off('zoomstart', onZoomStart);
      map.off('zoomend', onZoomEnd);
      container.removeEventListener('wheel', onWheel, { capture: true });
      if (timer !== undefined) clearTimeout(timer);
      settling = false;
      restoreCamera();
      restoreWheel();
      restoreSteps();
    }
  };
}

/**
 * `zoomIn` / `zoomOut` one MapML level from the level the map is on, or
 * is zooming to — Leaflet's `zoomIn` steps from its target zoom, so a
 * second click during the animation goes one level further. MapLibre's
 * step from the in-between zoom the animation has reached, which a
 * snap rounds back to the first click's level. Returns a function that
 * removes the wrappers.
 */
function snapZoomSteps(map: maplibregl.Map, scale: ZoomScale): () => void {
  let target: number | null = null;
  let stepping = false;
  // Any other movement (a drag, the wheel, a fly-to) supersedes the target.
  const onMoveStart = (): void => {
    if (!stepping) target = null;
  };
  const step = (direction: number, options?: maplibregl.AnimationOptions, eventData?: unknown) => {
    const from =
      target !== null && map.isMoving() ? target : Math.round(scale.toMapml(map.getZoom()));
    target = from + direction;
    stepping = true;
    try {
      return map.zoomTo(scale.toNative(target), options, eventData);
    } finally {
      stepping = false;
    }
  };
  map.on('movestart', onMoveStart);
  Object.assign(map, {
    zoomIn: ((options, eventData) => step(1, options, eventData)) as maplibregl.Map['zoomIn'],
    zoomOut: ((options, eventData) => step(-1, options, eventData)) as maplibregl.Map['zoomOut']
  });
  return () => {
    map.off('movestart', onMoveStart);
    delete (map as unknown as Record<string, unknown>).zoomIn;
    delete (map as unknown as Record<string, unknown>).zoomOut;
  };
}

/** The parts of MapLibre's `ScrollZoomHandler` {@link snapWheel} reads. */
interface ScrollZoomState {
  renderFrame?: (...args: unknown[]) => unknown;
  _delta?: number;
  _type?: 'wheel' | 'trackpad' | null;
  _targetZoom?: number;
}

/**
 * Snap the target of each mouse-wheel step to the next whole MapML level
 * in the wheel's direction. MapLibre's scroll handler computes the target
 * in `renderFrame`; it is asked for an unsnapped one (`zoomSnap` 0 for
 * the call) and that is snapped through `scale`, then kept within the
 * zoom the map can reach. As the target is in MapLibre's zoom, the
 * handler moves it with the globe's latitude as it zooms, so a globe's
 * wheel zoom ends on the level it was snapped to. Returns a function
 * that removes the wrapper.
 */
function snapWheel(map: maplibregl.Map, scale: ZoomScale): () => void {
  const handler = map.scrollZoom as unknown as ScrollZoomState;
  const original = handler.renderFrame;
  if (typeof original !== 'function') return () => {};
  handler.renderFrame = function (this: ScrollZoomState, ...args: unknown[]) {
    const delta = handler._delta ?? 0;
    if (delta === 0 || handler._type !== 'wheel') return original.apply(this, args);
    const zoomSnap = map.getZoomSnap();
    map.setZoomSnap(0);
    let result: unknown;
    try {
      result = original.apply(this, args);
    } finally {
      map.setZoomSnap(zoomSnap);
    }
    const raw = handler._targetZoom;
    if (typeof raw === 'number') {
      const { min, max } = scale.range();
      const z = Math.min(Math.max(level(scale.toMapml(raw), Math.sign(delta)), min), max);
      handler._targetZoom = Math.max(scale.toNative(z), scale.minNative());
    }
    return result;
  };
  return () => {
    delete handler.renderFrame;
  };
}

/**
 * Wrap `map`'s camera methods so they land on whole MapML levels — the
 * snapping MapLibre's `zoomSnap` does for a uniform grid, done through
 * `scale` at the latitude the camera moves to. MapLibre's internals
 * (gesture handlers, `fitBounds`, `zoomTo`) call these through `this`,
 * so the instance properties catch them too. Returns a function that
 * removes the wrappers.
 */
function snapCameraMethods(map: maplibregl.Map, scale: ZoomScale): () => void {
  const snapZoom = <T extends CameraOptionsWithZoom | undefined>(options: T, direction = 0): T => {
    if (options?.zoom === undefined) return options;
    const lat = latitudeOf(options.center);
    const z = level(scale.toMapml(options.zoom, lat), direction);
    return { ...options, zoom: scale.toNative(z, lat) };
  };

  const proto = Object.getPrototypeOf(map) as maplibregl.Map;
  const wrapped = {
    jumpTo: ((options, eventData) =>
      proto.jumpTo.call(map, snapZoom(options), eventData)) as maplibregl.Map['jumpTo'],
    easeTo: ((options, eventData) =>
      proto.easeTo.call(map, snapZoom(options), eventData)) as maplibregl.Map['easeTo'],
    flyTo: ((options, eventData) =>
      proto.flyTo.call(map, snapZoom(options), eventData)) as maplibregl.Map['flyTo'],
    cameraForBounds: ((bounds, options) =>
      snapZoom(proto.cameraForBounds.call(map, bounds, options), -1)) as maplibregl.Map['cameraForBounds']
  };
  Object.assign(map, wrapped);
  return () => {
    for (const key of Object.keys(wrapped)) delete (map as unknown as Record<string, unknown>)[key];
  };
}
