import * as maplibregl from 'maplibre-gl';
import { tileMatrixRows } from '../core/crs';
import { TRANSPARENT_TILE_PNG, decodeBlankTile } from './mapLibreMapTileProtocol';
import { loadTileImage, regridQuadTile, type RegridContext } from './regrid';

/**
 * `{z}/{x}/{y}` raster tiles whose zoom isn't MapLibre's tile zoom.
 *
 * A MapML CRS registered with MapLibre is drawn on a power-of-two quad
 * grid laid over its tile matrix (`core/zoomScale.ts` `quadGrid`). Where
 * MapML's zoom-0 matrix is more than one tile, as WGS84's 2×1 is, the
 * quad grid starts `k` levels above it: quad tile `(z + k)/x/y` is MapML
 * tile `z/x/y`. Where MapML's levels don't halve (CBMTILE), each quad
 * tile is composed out of MapML tiles of the level on screen
 * (`regrid.ts`). A tile URL template can do neither, so such a source's
 * tiles are `mapmlzxytile://<id>/{z}/{x}/{y}`, and this handler fills
 * the layer's own template with MapML's zoom (and, for a TMS layer, its
 * row counted from the bottom of MapML's matrix) and fetches it.
 *
 * Module-scoped registry, like the sibling `mapmlwmstile://` handler:
 * `maplibregl.addProtocol` is a global registration.
 */

export const MAPML_ZXY_TILE_PROTOCOL = 'mapmlzxytile';

export interface ZxyTileRegistryEntry {
  /** The layer's tile URL, with `{z}` / `{x}` / `{y}` in MapML's tile matrix. */
  template: string;
  /** MapLibre quad zoom − MapML tile zoom, for a native grid. */
  zoomOffset: number;
  /** The MapML CRS, for TMS rows. */
  projection: string;
  scheme: 'xyz' | 'tms';
  /** Present where quad tiles are composed out of MapML's (CBMTILE). */
  regrid?: RegridContext;
}

export const mapmlZxyTileRegistry = new Map<string, ZxyTileRegistryEntry>();

let registered = false;

/** Register the `mapmlzxytile://` handler, once. */
export function ensureMapmlZxyTileProtocol(): void {
  if (registered) return;
  registered = true;
  maplibregl.addProtocol(MAPML_ZXY_TILE_PROTOCOL, async (params, abortController) => {
    const match = /^mapmlzxytile:\/\/([^/]+)\/(\d+)\/(\d+)\/(\d+)$/.exec(params.url);
    if (match === null) {
      throw new Error(`Malformed ${MAPML_ZXY_TILE_PROTOCOL}:// URL: ${params.url}`);
    }
    const entry = mapmlZxyTileRegistry.get(decodeURIComponent(match[1]!));
    const [q, x, y] = [Number(match[2]), Number(match[3]), Number(match[4])];
    const init: RequestInit = {};
    if (params.credentials !== undefined) {
      init.credentials = params.credentials as RequestCredentials;
    }
    if (entry?.regrid) {
      const image = await regridQuadTile(
        entry.regrid,
        q,
        x,
        y,
        (z, col, row) => loadTileImage(mapmlTileUrl(entry, z, col, row), init),
        abortController.signal
      );
      return { data: image ?? (await decodeBlankTile()) };
    }
    const url = entry && zxyTileUrl(entry, q, x, y);
    // A removed layer, or a quad tile above MapML's zoom 0, has no tile.
    if (!url) return { data: TRANSPARENT_TILE_PNG.slice().buffer };
    const response = await fetch(url, { ...init, signal: abortController.signal });
    if (!response.ok) {
      throw new Error(`${MAPML_ZXY_TILE_PROTOCOL} fetch ${response.status} ${response.statusText}: ${url}`);
    }
    return { data: await response.arrayBuffer() };
  });
}

/**
 * The URL of MapLibre quad tile `q/x/y` in `entry`'s template, or null
 * when it is above MapML's zoom 0 (and so is no MapML tile).
 */
export function zxyTileUrl(entry: ZxyTileRegistryEntry, q: number, x: number, y: number): string | null {
  const z = q - entry.zoomOffset;
  if (z < 0) return null;
  return mapmlTileUrl(entry, z, x, y);
}

/** The URL of MapML tile `z/col/row` (`row` counted down from the top). */
export function mapmlTileUrl(entry: ZxyTileRegistryEntry, z: number, col: number, row: number): string {
  const y = entry.scheme === 'tms' ? tileMatrixRows(entry.projection, z) - 1 - row : row;
  return entry.template
    .split('{z}')
    .join(String(z))
    .split('{x}')
    .join(String(col))
    .split('{y}')
    .join(String(y));
}
