/**
 * MapML coordinate transforms, axis helpers, and the multi-CRS *extent
 * envelope* shape exposed by
 * `<mapml-viewer>.extent`, `<map-layer>.extent`, and
 * `<map-extent>.extent`.
 *
 * The envelope produced by {@link formatPcrsExtent} matches MapML.js's
 * `Util._convertAndFormatPCRS` output field-for-field so that author
 * code reading `viewer.extent.topLeft.pcrs.horizontal` etc. is
 * portable across the Leaflet-backed reference implementation and this
 * MapLibre-backed port.
 *
 * MapML.js reaches these transforms via `proj4leaflet` and the
 * `resolutions` table on each `M[projection]` object; the port's
 * equivalents are the {@link TiledCrs} objects in `./projections`. The
 * projection-taking functions here ({@link gcrsToPcrs},
 * {@link pcrsToTcrs}, …) work for every MapML CRS; OSMTILE keeps its
 * closed-form Web Mercator formulas (the `osmtile*` functions, which
 * are Leaflet's `CRS.EPSG3857`, as in MapML.js).
 *
 * MapML defines four coordinate reference systems that the URL template
 * engine and `<map-input>` bounds derivation care about
 * (https://maps4html.org/web-map-doc/docs/elements/input/#axis):
 *
 *   - **GCRS**: geographic WGS84 in degrees. Axes `longitude`, `latitude`.
 *   - **PCRS**: projected coordinates in the projection's native units
 *     (meters for OSMTILE). Axes `easting`, `northing`.
 *   - **TCRS**: tile-coordinate reference system, pixel-ish at a specific
 *     zoom (i.e. `pixel = tile * tileSize`). Axes `x`, `y`.
 *   - **TILEMATRIX**: integer tile column/row at a specific zoom. Axes
 *     `column`, `row`.
 *
 * The `MAP` / `TILE` CS (axes `i`, `j`) exist for click-to-query
 * templating; they are not usable to derive an extent bbox and are
 * therefore excluded from the CS helpers below.
 */

import type { MapmlProjection } from './projection';
import {
  MAX_MERCATOR_LATITUDE,
  getTiledCrs,
  tiledCrs,
  type MapmlCrsName
} from './projections';

export { MAX_MERCATOR_LATITUDE };

/**
 * A projection name the CRS functions accept: any MapML CRS (and the
 * port's `GLOBE` alias of OSMTILE). Unknown names are treated as OSMTILE
 * (MapML.js's `M.FALLBACK_PROJECTION`).
 */
export type AnyProjection = MapmlProjection | MapmlCrsName | (string & {});

/** Whether a projection is OSMTILE (or its `GLOBE` alias, or unknown). */
function isOsmtile(projection: AnyProjection): boolean {
  return tiledCrs(projection).name === 'OSMTILE';
}

/** MapML coordinate systems recognised for extent derivation. */
export type MapmlCS = 'TILEMATRIX' | 'PCRS' | 'GCRS' | 'TCRS';

/** A single 2D coordinate in the shape used by `topLeft.pcrs` / `topLeft.gcrs` etc. */
export interface MapmlCoord {
  horizontal: number;
  vertical: number;
}

/** One corner of an extent envelope; matches MapML.js's `topLeft` / `bottomRight`. */
export interface EnvelopeCorner {
  /** Per-zoom-level array (25 entries for OSMTILE), tile-pixel coordinates. */
  tcrs: MapmlCoord[];
  /** Per-zoom-level array (25 entries for OSMTILE), fractional tile column/row. */
  tilematrix: MapmlCoord[];
  /** Geographic WGS84 (`{ horizontal: lon, vertical: lat }`). */
  gcrs: MapmlCoord;
  /** Projected native units (`{ horizontal: easting, vertical: northing }` for OSMTILE). */
  pcrs: MapmlCoord;
}

/**
 * The multi-CRS extent envelope exposed by `<mapml-viewer>.extent`,
 * `<map-layer>.extent`, and `<map-extent>.extent`.
 *
 * Matches MapML.js's `map-extent` / `layer` / `mapml-viewer` `extent`
 * getter output. `zoom` uses the MapML.js field names (`minZoom` /
 * `maxZoom`, not `min` / `max`) so cross-implementation code reads the
 * same fields.
 */
export interface MapmlExtent {
  topLeft: EnvelopeCorner;
  bottomRight: EnvelopeCorner;
  /**
   * The native zooms (`minNativeZoom` / `maxNativeZoom`): a `<map-feature>`'s
   * own zoom, and for `<map-layer>` / `<map-extent>` the union of their
   * content's, as MapML.js's `zoomBounds`.
   */
  zoom: { minZoom: number; maxZoom: number; minNativeZoom?: number; maxNativeZoom?: number };
  projection: AnyProjection;
}

/** Internal representation of a PCRS bbox: `{ min: [x, y], max: [x, y] }`. */
export interface PcrsBounds {
  min: [number, number];
  max: [number, number];
}

/** OSMTILE tile size (pixels) \u2014 matches Leaflet/MapLibre's default. */
export const OSMTILE_TILE_SIZE = 256;

/** OSMTILE semi-major radius, meters (WGS84 sphere for Web Mercator). */
const R_EARTH = 6378137;

/** OSMTILE half-circumference, meters. Web Mercator wraps at \u00b1this. */
const HALF_C = Math.PI * R_EARTH; // \u2248 20037508.342789244


/** * OSMTILE resolutions table \u2014 meters per pixel at each zoom level.
 *
 * Matches MapML.js's `M.OSMTILE.options.resolutions` byte-for-byte
 * (`src/mapml/GlobalM.js`). 25 entries, so max zoom = 24. The
 * multi-CRS envelope's `tcrs` / `tilematrix` arrays have this length.
 */
export const OSMTILE_RESOLUTIONS: readonly number[] = [
  156543.0339, 78271.51695, 39135.758475, 19567.8792375, 9783.93961875,
  4891.969809375, 2445.9849046875, 1222.9924523438, 611.49622617188,
  305.74811308594, 152.87405654297, 76.437028271484, 38.218514135742,
  19.109257067871, 9.5546285339355, 4.7773142669678, 2.3886571334839,
  1.1943285667419, 0.59716428337097, 0.29858214168549, 0.14929107084274,
  0.074645535421371, 0.03732276771068573, 0.018661383855342865,
  0.009330691927671432495
];

/**
 * OSMTILE forward: `[lon, lat]` in degrees \u2192 `[easting, northing]` in
 * meters (EPSG:3857). Latitudes are clamped to the Web Mercator valid
 * range (\u00b185.05112878\u00b0) to avoid `-Infinity` at the poles.
 */
export function osmtileGcrsToPcrs(lon: number, lat: number): [number, number] {
  const clampedLat = Math.max(
    Math.min(lat, MAX_MERCATOR_LATITUDE),
    -MAX_MERCATOR_LATITUDE
  );
  const x = (lon * HALF_C) / 180;
  const y = Math.log(Math.tan(((90 + clampedLat) * Math.PI) / 360)) * R_EARTH;
  return [x, y];
}

/** OSMTILE inverse: `[easting, northing]` meters \u2192 `[lon, lat]` degrees. */
export function osmtilePcrsToGcrs(x: number, y: number): [number, number] {
  const lon = (x / HALF_C) * 180;
  const lat = (Math.atan(Math.exp(y / R_EARTH)) * 360) / Math.PI - 90;
  return [lon, lat];
}

/**
 * OSMTILE PCRS \u2192 TCRS at a zoom level.
 *
 * Matches Leaflet's `L.CRS.EPSG3857.transformation.transform(pcrs, scale)`
 * (with `scale = 256 * 2^zoom`), which is what MapML.js's
 * `_convertAndFormatPCRS` calls per-zoom to build the TCRS array. Y is
 * flipped: TCRS Y grows southward (pixel space), while PCRS Y grows
 * northward.
 */
export function osmtilePcrsToTcrs(x: number, y: number, zoom: number): MapmlCoord {
  const scale = OSMTILE_TILE_SIZE * Math.pow(2, zoom);
  return {
    horizontal: scale * (x / (2 * HALF_C) + 0.5),
    vertical: scale * (-y / (2 * HALF_C) + 0.5)
  };
}

/**
 * OSMTILE `<map-input axis="column|row" units="tilematrix">` \u2192 PCRS.
 *
 * Closed-form: at zoom `z` the tile grid spans `2^z` tiles across; row
 * 0 is at the top (Web Mercator convention, matching MapML.js's
 * TILEMATRIX axis). Returns PCRS in meters.
 */
export function osmtileTilematrixToPcrs(
  col: number,
  row: number,
  zoom: number
): [number, number] {
  const n = Math.pow(2, zoom);
  const x = 2 * HALF_C * (col / n - 0.5);
  const y = 2 * HALF_C * (0.5 - row / n);
  return [x, y];
}

/**
 * OSMTILE `<map-input axis="x|y" units="tcrs">` \u2192 PCRS.
 * TCRS is tile-pixel space at a specific zoom (`tile = pixel / tileSize`).
 */
export function osmtileTcrsToPcrs(
  x: number,
  y: number,
  zoom: number
): [number, number] {
  return osmtileTilematrixToPcrs(x / OSMTILE_TILE_SIZE, y / OSMTILE_TILE_SIZE, zoom);
}

/** `[lon, lat]` → PCRS `[x, y]` in `projection` (MapML.js `M[p].project`). */
export function gcrsToPcrs(
  projection: AnyProjection,
  lon: number,
  lat: number
): [number, number] {
  return isOsmtile(projection) ? osmtileGcrsToPcrs(lon, lat) : tiledCrs(projection).project(lon, lat);
}

/** PCRS `[x, y]` in `projection` → `[lon, lat]` (MapML.js `M[p].unproject`). */
export function pcrsToGcrs(
  projection: AnyProjection,
  x: number,
  y: number
): [number, number] {
  return isOsmtile(projection) ? osmtilePcrsToGcrs(x, y) : tiledCrs(projection).unproject(x, y);
}

/**
 * PCRS → TCRS pixels at a zoom (MapML.js
 * `M[p].transformation.transform(pcrs, M[p].scale(zoom))`).
 */
export function pcrsToTcrs(
  projection: AnyProjection,
  x: number,
  y: number,
  zoom: number
): MapmlCoord {
  if (isOsmtile(projection)) return osmtilePcrsToTcrs(x, y, zoom);
  const crs = tiledCrs(projection);
  const [h, v] = crs.transform(x, y, crs.scale(zoom));
  return { horizontal: h, vertical: v };
}

/** TCRS pixels at a zoom → PCRS (MapML.js `Util.pixelToPCRSPoint`). */
export function tcrsToPcrs(
  projection: AnyProjection,
  x: number,
  y: number,
  zoom: number
): [number, number] {
  if (isOsmtile(projection)) return osmtileTcrsToPcrs(x, y, zoom);
  const crs = tiledCrs(projection);
  return crs.untransform(x, y, crs.scale(zoom));
}

/** Tile column / row at a zoom → PCRS of the tile's top-left corner. */
export function tilematrixToPcrs(
  projection: AnyProjection,
  col: number,
  row: number,
  zoom: number
): [number, number] {
  if (isOsmtile(projection)) return osmtileTilematrixToPcrs(col, row, zoom);
  const size = tiledCrs(projection).tileSize;
  return tcrsToPcrs(projection, col * size, row * size, zoom);
}

/** A projection's tile size in pixels (`M[p].options.crs.tile.bounds.max.x`). */
export function projectionTileSize(projection: AnyProjection): number {
  return tiledCrs(projection).tileSize;
}

/** Whether `projection` names a MapML CRS (or the `GLOBE` alias). */
export function isKnownProjection(projection: string): boolean {
  return getTiledCrs(projection) !== undefined;
}

/**
 * Map a `<map-input axis>` value to the coordinate system it belongs to,
 * or `null` for the `i`/`j` axes (pixel-in-map / pixel-in-tile, not
 * usable to derive a geographic bbox).
 */
export function axisToCS(axis: string): MapmlCS | null {
  switch (axis.toLowerCase()) {
    case 'column':
    case 'row':
      return 'TILEMATRIX';
    case 'easting':
    case 'northing':
      return 'PCRS';
    case 'longitude':
    case 'latitude':
      return 'GCRS';
    case 'x':
    case 'y':
      return 'TCRS';
    default:
      return null;
  }
}

/** Given a CS, return `[horizontalAxis, verticalAxis]`. */
export function csToAxes(cs: MapmlCS): [string, string] {
  switch (cs) {
    case 'TILEMATRIX':
      return ['column', 'row'];
    case 'PCRS':
      return ['easting', 'northing'];
    case 'GCRS':
      return ['longitude', 'latitude'];
    case 'TCRS':
      return ['x', 'y'];
  }
}

/**
 * `'x'` for horizontal axes (`column`, `easting`, `longitude`, `x`),
 * `'y'` for vertical axes (`row`, `northing`, `latitude`, `y`), `null`
 * otherwise.
 */
export function axisToXY(axis: string): 'x' | 'y' | null {
  switch (axis.toLowerCase()) {
    case 'column':
    case 'easting':
    case 'longitude':
    case 'x':
      return 'x';
    case 'row':
    case 'northing':
    case 'latitude':
    case 'y':
      return 'y';
    default:
      return null;
  }
}

/** A pair of horizontal `[min, max]` and vertical `[min, max]` in a single CS. */
export interface AxisPair {
  cs: MapmlCS;
  hMin: number;
  hMax: number;
  vMin: number;
  vMax: number;
}

/**
 * Convert an {@link AxisPair} to a {@link PcrsBounds}. `zoom` is only
 * consulted for `TILEMATRIX` / `TCRS` (where the mapping to projected
 * space depends on the tile pyramid level); pass `0` when unused.
 *
 * Unknown projections return `null` \u2014 the caller warns.
 *
 * The output PCRS bbox is *normalised* so `min.x < max.x` and
 * `min.y < max.y`, independent of the incoming axis orientation
 * (TILEMATRIX / TCRS grow their vertical axis southward; PCRS / GCRS
 * grow theirs northward).
 */
export function axisPairToPcrsBounds(
  pair: AxisPair,
  projection: AnyProjection,
  zoom: number
): PcrsBounds | null {
  if (!isKnownProjection(projection)) return null;
  const { cs, hMin, hMax, vMin, vMax } = pair;
  const hLo = Math.min(hMin, hMax);
  const hHi = Math.max(hMin, hMax);
  const vLo = Math.min(vMin, vMax);
  const vHi = Math.max(vMin, vMax);
  switch (cs) {
    case 'PCRS':
      return { min: [hLo, vLo], max: [hHi, vHi] };
    case 'GCRS': {
      return gcrsCornersToPcrsBounds([hLo, vLo], [hHi, vHi], projection);
    }
    case 'TILEMATRIX': {
      // Vertical axis grows southward: max row \u2192 south (min y in PCRS),
      // min row \u2192 north (max y in PCRS).
      const [xLo, yHiPcrs] = tilematrixToPcrs(projection, hLo, vLo, zoom);
      const [xHi, yLoPcrs] = tilematrixToPcrs(projection, hHi, vHi, zoom);
      return { min: [xLo, yLoPcrs], max: [xHi, yHiPcrs] };
    }
    case 'TCRS': {
      const [xLo, yHiPcrs] = tcrsToPcrs(projection, hLo, vLo, zoom);
      const [xHi, yLoPcrs] = tcrsToPcrs(projection, hHi, vHi, zoom);
      return { min: [xLo, yLoPcrs], max: [xHi, yHiPcrs] };
    }
  }
}

/**
 * Whole-projection PCRS bbox (`M[p].options.bounds`). OSMTILE (and its
 * GLOBE alias) spans \u00b1{@link HALF_C} on both axes.
 */
export function projectionPcrsBounds(projection: AnyProjection): PcrsBounds {
  if (isOsmtile(projection)) return { min: [-HALF_C, -HALF_C], max: [HALF_C, HALF_C] };
  const { min, max } = tiledCrs(projection).bounds;
  return { min: [min[0], min[1]], max: [max[0], max[1]] };
}

/**
 * Rows in `projection`'s tile matrix at `zoom` — what a TMS row is
 * counted back from. `2^zoom` for OSMTILE; WGS84's matrix is twice as
 * wide as it is tall, so its rows are `2^zoom` too.
 */
export function tileMatrixRows(projection: AnyProjection, zoom: number): number {
  if (isOsmtile(projection)) return 2 ** zoom;
  const crs = tiledCrs(projection);
  const height = crs.origin[1] - crs.bounds.min[1];
  return Math.ceil(height / (crs.tileSize * crs.resolutions[zoom]!) - 1e-9);
}

/** Points sampled along each edge of a box by {@link pcrsBoundsToLngLatBox}. */
const EDGE_SAMPLES = 16;

/**
 * A `[west, south, east, north]` lng/lat box containing PCRS `bounds`,
 * for a MapLibre source's `bounds` (which MapLibre projects back to its
 * own grid, so a box too big only costs tile requests). OSMTILE's
 * boxes stay boxes; elsewhere it is the box around points along the
 * edges, taken to the pole and right round when the box contains one.
 */
export function pcrsBoundsToLngLatBox(
  projection: AnyProjection,
  bounds: PcrsBounds
): [number, number, number, number] {
  const [minX, minY] = bounds.min;
  const [maxX, maxY] = bounds.max;
  if (isOsmtile(projection)) {
    const [west, south] = osmtilePcrsToGcrs(minX, minY);
    const [east, north] = osmtilePcrsToGcrs(maxX, maxY);
    return [west, south, east, north];
  }
  let west = Infinity;
  let south = Infinity;
  let east = -Infinity;
  let north = -Infinity;
  const add = (x: number, y: number): void => {
    const [lon, lat] = pcrsToGcrs(projection, x, y);
    if (!Number.isFinite(lon) || !Number.isFinite(lat)) return;
    west = Math.min(west, lon);
    east = Math.max(east, lon);
    south = Math.min(south, lat);
    north = Math.max(north, lat);
  };
  for (let i = 0; i <= EDGE_SAMPLES; i++) {
    const t = i / EDGE_SAMPLES;
    const x = minX + t * (maxX - minX);
    const y = minY + t * (maxY - minY);
    add(x, minY);
    add(x, maxY);
    add(minX, y);
    add(maxX, y);
  }
  const contains = (lat: number): boolean => {
    const [x, y] = gcrsToPcrs(projection, 0, lat);
    return x >= minX && x <= maxX && y >= minY && y <= maxY;
  };
  if (contains(90)) [north, west, east] = [90, -180, 180];
  if (contains(-90)) [south, west, east] = [-90, -180, 180];
  return [
    Math.max(-180, west),
    Math.max(-90, south),
    Math.min(180, east),
    Math.min(90, north)
  ];
}

/**
 * Maximum zoom level supported by a projection's tile pyramid (i.e.
 * `resolutions.length - 1`). 24 for OSMTILE, matching MapML.js.
 */
export function projectionMaxZoom(projection: AnyProjection): number {
  return tiledCrs(projection).resolutions.length - 1;
}

/**
 * Emit the multi-CRS extent envelope for a PCRS bounding box.
 *
 * Field-for-field equivalent to MapML.js's
 * `Util._convertAndFormatPCRS(pcrsBounds, crs, projection)`
 * (`src/mapml/utils/Util.js`), so author code reading fields like
 * `extent.topLeft.pcrs.horizontal`, `extent.topLeft.gcrs.vertical`,
 * `extent.topLeft.tilematrix[3]`, `extent.zoom.maxZoom`, etc. is
 * portable across implementations.
 *
 * The `tcrs` and `tilematrix` arrays have one entry per zoom level in
 * the projection's `resolutions` table (25 entries for OSMTILE); the
 * `gcrs` and `pcrs` corners are single points, independent of zoom.
 */
export function formatPcrsExtent(
  pcrsBounds: PcrsBounds,
  projection: AnyProjection,
  zoomRange: MapmlExtent['zoom']
): MapmlExtent {
  const levels = tiledCrs(projection).resolutions.length;
  const tileSize = projectionTileSize(projection);
  const [minX, minY] = pcrsBounds.min;
  const [maxX, maxY] = pcrsBounds.max;

  const tcrsTopLeft: MapmlCoord[] = [];
  const tcrsBottomRight: MapmlCoord[] = [];
  const tileMatrixTopLeft: MapmlCoord[] = [];
  const tileMatrixBottomRight: MapmlCoord[] = [];

  for (let z = 0; z < levels; z++) {
    const min = pcrsToTcrs(projection, minX, minY, z);
    const max = pcrsToTcrs(projection, maxX, maxY, z);
    // In pixel space, y grows southward: PCRS min.y \u2192 pixel max.y, and
    // vice versa. topLeft therefore combines min.x (west) with max.y
    // (north \u2192 small pixel y).
    tcrsTopLeft.push({ horizontal: min.horizontal, vertical: max.vertical });
    tcrsBottomRight.push({
      horizontal: max.horizontal,
      vertical: min.vertical
    });
    tileMatrixTopLeft.push({
      horizontal: min.horizontal / tileSize,
      vertical: max.vertical / tileSize
    });
    tileMatrixBottomRight.push({
      horizontal: max.horizontal / tileSize,
      vertical: min.vertical / tileSize
    });
  }

  const [minLon, minLat] = pcrsToGcrs(projection, minX, minY);
  const [maxLon, maxLat] = pcrsToGcrs(projection, maxX, maxY);

  return {
    topLeft: {
      tcrs: tcrsTopLeft,
      tilematrix: tileMatrixTopLeft,
      gcrs: { horizontal: minLon, vertical: maxLat },
      pcrs: { horizontal: minX, vertical: maxY }
    },
    bottomRight: {
      tcrs: tcrsBottomRight,
      tilematrix: tileMatrixBottomRight,
      gcrs: { horizontal: maxLon, vertical: minLat },
      pcrs: { horizontal: maxX, vertical: minY }
    },
    zoom: { ...zoomRange },
    projection
  };
}

/**
 * Convert a GCRS `[southWest, northEast]` pair to a normalised PCRS bbox
 * by projecting the two corners (MapML.js `Util.boundsToPCRSBounds`).
 */
export function gcrsCornersToPcrsBounds(
  southWest: readonly [number, number],
  northEast: readonly [number, number],
  projection: AnyProjection = 'OSMTILE'
): PcrsBounds {
  const [swX, swY] = gcrsToPcrs(projection, southWest[0], southWest[1]);
  const [neX, neY] = gcrsToPcrs(projection, northEast[0], northEast[1]);
  return {
    min: [Math.min(swX, neX), Math.min(swY, neY)],
    max: [Math.max(swX, neX), Math.max(swY, neY)]
  };
}

/** The PCRS box of a {@link MapmlExtent} (its top-left and bottom-right). */
export function extentPcrsBounds(extent: MapmlExtent): PcrsBounds {
  return {
    min: [extent.topLeft.pcrs.horizontal, extent.bottomRight.pcrs.vertical],
    max: [extent.bottomRight.pcrs.horizontal, extent.topLeft.pcrs.vertical]
  };
}

/** Union of two PCRS bboxes. */
export function unionPcrsBounds(a: PcrsBounds, b: PcrsBounds): PcrsBounds {
  return {
    min: [Math.min(a.min[0], b.min[0]), Math.min(a.min[1], b.min[1])],
    max: [Math.max(a.max[0], b.max[0]), Math.max(a.max[1], b.max[1])]
  };
}

/**
 * True when two PCRS bboxes share any interior points. Matches
 * Leaflet's `L.Bounds.overlaps` semantic used by MapML.js's
 * `TemplatedTileLayer.isVisible()` \u2014 boxes that only touch along
 * an edge are *not* considered overlapping (strict inequality). Used
 * to decide whether a `<map-link>` template contributes at the current
 * map view.
 */
export function pcrsBoundsOverlap(a: PcrsBounds, b: PcrsBounds): boolean {
  return (
    a.min[0] < b.max[0] &&
    a.max[0] > b.min[0] &&
    a.min[1] < b.max[1] &&
    a.max[1] > b.min[1]
  );
}
