/**
 * Stylesheet for the {@link ContextMenu} overlay (and the layer and extent
 * menus, which share its classes), injected into the viewer's shadow root.
 * Ported from MapML.js's mapml.css (the .mapml-contextmenu rules, the
 * .mapml-button reset its items carry, and the font the menu inherits from
 * .leaflet-container), so the menu looks as it does there. Positioning stays
 * the port's: the menu is placed over the canvas with left/top.
 */
export const contextMenuCss = /* css */ `
.mapml-contextmenu {
  border-radius: 4px;
  padding: 4px 0;
  background-color: #fff;
  cursor: default;
  position: absolute;
  width: fit-content;
  display: inline-block;
  z-index: 10001;
  box-shadow: rgb(0 0 0 / 30%) 0px 1px 4px -1px;
  font-family: "Helvetica Neue", Arial, Helvetica, sans-serif;
  font-size: 12px;
  line-height: 1.5;
  user-select: none;
}
.mapml-contextmenu[hidden] {
  display: none;
}
.mapml-contextmenu button.mapml-contextmenu-item {
  background-color: transparent;
  border: none;
  border-radius: 0;
  margin: 0;
  overflow: hidden;
  text-align: inherit;
  text-transform: none;
  appearance: none;
  font: inherit;
  color: #222;
  font-size: 12px;
  line-height: 20px;
  text-decoration: none;
  padding: 0 12px;
  border-top: 1px solid transparent;
  border-bottom: 1px solid transparent;
  cursor: default;
  width: 100%;
  display: block;
}
.mapml-contextmenu button.mapml-contextmenu-item:hover {
  background-color: #f4f4f4;
  border-top: 1px solid #f0f0f0;
  border-bottom: 1px solid #f0f0f0;
}
.mapml-contextmenu button.mapml-contextmenu-item:disabled {
  color: #bbb;
  opacity: 0.3;
}
.mapml-contextmenu-item > * {
  pointer-events: none;
}
.mapml-contextmenu-separator {
  border-bottom: 1px solid #e3e3e3;
  margin: 5px 0;
}
.mapml-contextmenu-item[aria-controls] span::after {
  content: ">";
}
@supports (list-style-type: disclosure-open) {
  .mapml-contextmenu-item[aria-controls] span {
    display: inline-block;
  }
  .mapml-contextmenu-item[aria-controls] span::after {
    content: "";
    display: list-item;
    list-style-type: disclosure-closed;
    margin-inline-start: 20px;
  }
}
`;
