/**
 * The MapML projection names a `<mapml-viewer projection>` accepts.
 *
 * MapML.js defines `OSMTILE`, `WGS84`, `CBMTILE` and `APSTILE`
 * (`src/mapml/GlobalM.js`); the port draws each of them: OSMTILE as
 * MapLibre's built-in `mercator`, the others as projections registered
 * with MapLibre's `addProjection` (see `renderer/maplibreProjection.ts`).
 * `GLOBE` is the port's deprecated alias of OSMTILE drawn on the globe;
 * the viewer folds it into `view="globe"`.
 *
 * A page can define more with the viewer's `defineCustomProjection`
 * (`core/projections.ts` {@link defineCustomTiledCrs}), registered with
 * `addProjection` like the built-in ones. Any other name is undefined:
 * the viewer waits for it to be defined, as MapML.js does, then warns
 * and falls back to OSMTILE (`M.FALLBACK_PROJECTION`).
 */
import { isCustomProjection } from './projections';

/** The built-in projections the viewer accepts. */
export const MAPML_PROJECTIONS = ['OSMTILE', 'WGS84', 'CBMTILE', 'APSTILE', 'GLOBE'] as const;

/** A built-in projection name, or the name of a custom projection. */
export type MapmlProjection = (typeof MAPML_PROJECTIONS)[number] | (string & {});

/** Whether `value` names a built-in projection or a defined custom one. */
export function isMapmlProjection(value: string): value is MapmlProjection {
  return (MAPML_PROJECTIONS as readonly string[]).includes(value) || isCustomProjection(value);
}

/**
 * Resolves once `projection` names a defined projection; rejects after 5
 * seconds. Ports MapML.js's `whenProjectionDefined`, polling included.
 */
export function whenProjectionDefined(projection: string): Promise<void> {
  return new Promise((resolve, reject) => {
    if (isMapmlProjection(projection)) {
      resolve();
      return;
    }
    const interval = setInterval(() => {
      if (isMapmlProjection(projection)) {
        clearInterval(interval);
        clearTimeout(timer);
        resolve();
      }
    }, 200);
    const timer = setTimeout(() => {
      clearInterval(interval);
      reject(new Error('Timeout reached waiting for projection to be defined'));
    }, 5000);
  });
}

/**
 * Whether `projection` is drawn in Web Mercator — the only projection
 * MapLibre's globe can draw (OSMTILE and its `GLOBE` alias).
 */
export function isWebMercatorProjection(projection: string): boolean {
  return projection === 'OSMTILE' || projection === 'GLOBE';
}
